import { ReviewResult } from '../types';
import {
  type PreparedProviderInvocation,
  type ProviderCredentialLease,
} from './prepared-invocation';

export interface ProviderExecutionPolicy {
  canStartOptionalRetry(): boolean;
  clampTimeoutMs(requestedTimeoutMs: number): number;
}

export abstract class Provider {
  constructor(public readonly name: string) {}

  abstract review(
    prompt: string,
    timeoutMs: number,
    executionPolicy?: ProviderExecutionPolicy
  ): Promise<ReviewResult>;

  async prepareInvocation(
    _prompt: string,
    _timeoutMs: number,
    _executionPolicy?: ProviderExecutionPolicy
  ): Promise<PreparedProviderInvocation> {
    throw new Error(`provider_preparation_not_supported:${this.name}`);
  }

  async executePreparedInvocation(
    _invocation: PreparedProviderInvocation,
    _credentialLease?: ProviderCredentialLease,
    _signal?: AbortSignal
  ): Promise<ReviewResult> {
    throw new Error(`provider_prepared_execution_not_supported:${this.name}`);
  }

  /**
   * Health check to verify provider responsiveness before running full review
   * Uses a realistic mini code review task to better predict actual performance
   * @param timeoutMs - Maximum time to wait for response (default 30s)
   * @returns true if provider is responsive, false otherwise
   */
  async healthCheck(timeoutMs: number = 30000): Promise<boolean> {
    try {
      // Use a realistic code review task that exercises the same code paths
      // as the full review but with minimal input
      const testPrompt = `Review this code change and respond with a brief finding in JSON format:
\`\`\`typescript
function add(a, b) {
  return a + b;  // Missing type annotations
}
\`\`\`

Respond with: {"findings": [{"file": "test.ts", "line": 1, "severity": "minor", "title": "title", "message": "msg"}]}`;

      await this.review(testPrompt, timeoutMs);
      return true;
    } catch {
      return false;
    }
  }

  static validate(name: string): boolean {
    const pattern =
      /^(opencode\/[\w.:~-]+|openrouter\/[\w.:~-]+(?:\/[\w.:~-]+)*(?:#\d+)?|claude\/[\w.:~-]+|codex\/[\w.:~-]+|codex-openrouter\/[\w.:~-]+(?:\/[\w.:~-]+)*|gemini\/[\w.:~-]+)$/i;
    return pattern.test(name);
  }
}

export class RateLimitError extends Error {
  constructor(
    message: string,
    public readonly retryAfterSeconds?: number
  ) {
    super(message);
    this.name = 'RateLimitError';
  }
}
